import * as React from "react";

export type PhotoFrameIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function PhotoFrameIcon({ size = 20, ...props }: PhotoFrameIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="5" width="16" height="14" rx="1.5" /><circle cx="9" cy="10" r="1.5" /><path d="M4 16.5 10 11l4 3.5 2-2 4 3.5" />
    </svg>
  );
}
